Settings.Decl:
type Settings struct {
	// Notify receives every new proposal; empty sends nothing.
	Notify string `db:"notify"`
	// ConfirmMail sends submitters a confirmation of their proposal.
	ConfirmMail bool `db:"confirm_mail"`
	// DecisionMail tells submitters when their proposal is accepted or rejected.
	DecisionMail bool `db:"decision_mail"`
}

Templates.Starter:
{{/* @dot github.com/donseba/go-webthings/modules/submissions.FormView */}}
{{/* Starting point generated by WebThings: a complete proposal form. */}}
<main id="content">
    <h1>{{.Title}}</h1>

    {{/* The form returns the visitor here, to the element with the id {{.Key}}. */}}
    <section id="{{.Key}}">
        {{if eq .Result "sent"}}
            <p>Thank you! The editors will read your proposal.</p>
        {{else}}
            {{if eq .Result "invalid"}}<p>Please fill in every field. Images are JPEG, PNG or GIF up to {{.MaxImageMB}} MB.</p>{{end}}
            {{if eq .Result "throttled"}}<p>You sent several proposals already. Please try again later.</p>{{end}}

            {{form_open .Form}}
                {{form_field .Form "name" nil}}
                {{form_field .Form "email" nil}}
                {{form_field .Form "title" nil}}
                {{form_field .Form "text" nil}}
                {{form_field .Form "image" nil}}

                <button type="submit">Send</button>
            {{form_close}}
        {{end}}
    </section>
</main>

Mail.Starter:
{{/* @dot github.com/donseba/go-webthings/modules/submissions.MailView */}}
{{/* Sent to the submitter after sending a proposal, when the settings ask for it. */}}
{{define "subject"}}{{tl localizer "We received your proposal"}}: {{.Title}}{{end}}

{{define "text"}}
{{tl localizer "Hello %s," .Name}}

{{tl localizer "Thank you for your proposal. The editors will read it and decide whether to publish it."}}

{{.Title}}
{{end}}

{{/* @dot github.com/donseba/go-webthings/modules/submissions.MailView */}}
{{/* Sent to the submitter when an editor accepts the proposal, when the settings ask for it. */}}
{{define "subject"}}{{tl localizer "Your proposal was accepted"}}: {{.Title}}{{end}}

{{define "text"}}
{{tl localizer "Hello %s," .Name}}

{{tl localizer "Good news: the editors accepted your proposal. It will be published after editing."}}

{{.Title}}
{{end}}

{{/* @dot github.com/donseba/go-webthings/modules/submissions.MailView */}}
{{/* Sent to the submitter when an editor rejects the proposal, when the settings ask for it. */}}
{{define "subject"}}{{tl localizer "About your proposal"}}: {{.Title}}{{end}}

{{define "text"}}
{{tl localizer "Hello %s," .Name}}

{{tl localizer "Thank you for your proposal. The editors decided not to publish it."}}

{{.Title}}
{{end}}

{{/* @dot github.com/donseba/go-webthings/modules/submissions.MailView */}}
{{/* Sent to the notification address of the settings, in the admin's language. Replying answers the submitter. */}}
{{define "subject"}}{{tl localizer "New proposal"}}: {{.Title}}{{end}}

{{define "text"}}
{{.Name}} <{{.Email}}>

{{.Title}}

{{.Body}}
{{with .ImageURL}}
{{.}}
{{end}}
{{tl localizer "Review the proposal:"}}
{{.AdminURL}}
{{end}}

Types.Decl:
type FormView struct {
	// Key is the instance key; results arrive as ?<key>=<result>, and the
	// form returns the visitor to the element with the id Key.
	Key string
	// Title is the title of the page the module is placed on.
	Title string
	// Action is the address the form posts to.
	Action string
	// Result is "sent" after a proposal was received, "invalid" when it was
	// refused, "throttled" after too many proposals, empty otherwise.
	Result string
	// MaxImageMB is the largest image visitors can add, in megabytes.
	MaxImageMB int
	// Form is the form's model (ProposalInput) for go-form's template
	// functions, such as {{form_open .Form}} and {{form_field .Form "title"
	// nil}}.
	Form form.RenderModel
}

type ListView struct {
	Title string
	// SettingsURL is set for editors who may change the settings.
	SettingsURL string
	// TrashURL shows the instance's deleted proposals.
	TrashURL string
	// Filters switch between the statuses; new ones are counted.
	Filters admin.Tabs
	Rows    []Row
	Pager   admin.Pager
}

type MailView struct {
	Submission
	// ImageURL is the absolute address of the image; empty without one, and
	// in mail to the submitter.
	ImageURL string
	// AdminURL opens the submission in the admin; empty in mail to the
	// submitter.
	AdminURL string
}

type Proposal struct {
	Name  string
	Email string
	Title string
	// Body is plain text or Markdown.
	Body string
	// MediaID is the uploaded image in the media library, or empty.
	MediaID string
	Locale  string
}

type Row struct {
	URL    string
	Date   string
	Title  string
	Name   string
	Locale string
	// Status is the translated status label.
	Status string
}

type Service struct {
	// contains unexported fields
}

type Settings struct {
	// Notify receives every new proposal; empty sends nothing.
	Notify string `db:"notify"`
	// ConfirmMail sends submitters a confirmation of their proposal.
	ConfirmMail bool `db:"confirm_mail"`
	// DecisionMail tells submitters when their proposal is accepted or rejected.
	DecisionMail bool `db:"decision_mail"`
}
